import React from 'react';

export default function Teachers() {
  const teacherDetails = [
    { name: "Nalinda Jayasinghe", sub: "Mathematics", degree: "B.Sc. (Mathematics) - University of Colombo", tel: "077-3456789" },
    { name: "Buddhika Darshani", sub: "Science & Mathematics", degree: "B.Sc. (Physical Science) - University of Sri Jayewardenepura", tel: "071-2345678" },
    { name: "Prasiddha Dissanayake", sub: "Accounting", degree: "B.Sc. (Accounting) / ACA Member", tel: "071-8901234" },
    { name: "Chamara Rajapaksha", sub: "Commerce & Business Studies", degree: "B.Sc. (Business Administration) - USJP", tel: "077-9012345" },
    { name: "Manoj Salinda", sub: "Physics", degree: "B.Sc. (Physics Special) - University of Colombo", tel: "076-0123456" },
    { name: "Sajith Gunaratne", sub: "Sinhala & History", degree: "BA (Hons) in Sinhala - University of Kelaniya", tel: "076-4567890" },
    { name: "Ranga Rajapaksha", sub: "English Language", degree: "BA in English Studies", tel: "072-5678901" },
    { name: "Chamika Jayaweera", sub: "ICT", degree: "B.Sc. in ICT - BIT (University of Moratuwa)", tel: "070-6789012" }
  ];

  return (
    <div style={{ padding: '60px 20px', maxWidth: '1100px', margin: '0 auto' }}>
      <h2 style={{ textAlign: 'center', color: '#1e3a8a', marginBottom: '10px', fontSize: '28px', fontWeight: 'bold' }}>Academic Faculty</h2>
      <p style={{ textAlign: 'center', color: '#666', marginBottom: '40px' }}>Meet our highly qualified professional lecturers.</p>
      
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '25px' }}>
        {teacherDetails.map((t, idx) => (
          <div key={idx} style={{ backgroundColor: '#fff', padding: '30px', borderRadius: '15px', textAlign: 'center', boxShadow: '0 10px 20px rgba(0,0,0,0.05)', borderTop: '5px solid #059669' }}>
            <div style={{ fontSize: '50px', marginBottom: '15px' }}>👨‍🏫</div>
            <h3 style={{ margin: '0 0 5px 0', fontSize: '20px', color: '#1f2937', fontWeight: 'bold' }}>{t.name}</h3>
            <p style={{ color: '#059669', fontWeight: 'bold', margin: '0 0 15px 0', fontSize: '14px', textTransform: 'uppercase' }}>{t.sub}</p>
            <div style={{ textAlign: 'left', fontSize: '14px', backgroundColor: '#f9fafb', padding: '15px', borderRadius: '10px' }}>
              <p style={{ margin: '0 0 8px 0', lineHeight: '1.4' }}>🎓 <strong>Qualifications:</strong> <br /> <span style={{ color: '#4b5563' }}>{t.degree}</span></p>
              <p style={{ margin: 0 }}>📞 <strong>Contact Hotline:</strong> <span style={{ color: '#4b5563' }}>{t.tel}</span></p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
